BEGIN;
CREATE TABLE hr_compensation_history(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,base_salary DECIMAL(14,2) NOT NULL CHECK(base_salary>=0),variable_target DECIMAL(14,2) NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'TRY',salary_type TEXT NOT NULL DEFAULT 'GROSS',pay_frequency TEXT NOT NULL DEFAULT 'MONTHLY',effective_from DATE NOT NULL,effective_to DATE,reason TEXT,approved_by TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(effective_to IS NULL OR effective_to>=effective_from),UNIQUE(tenant_id,staff_id,effective_from));
CREATE INDEX hr_compensation_current_idx ON hr_compensation_history(tenant_id,company_id,staff_id,effective_from DESC);
CREATE TABLE hr_benefit_assignments(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,benefit_type TEXT NOT NULL,name TEXT NOT NULL,amount DECIMAL(14,2),currency TEXT NOT NULL DEFAULT 'TRY',employer_cost DECIMAL(14,2),payroll_taxable BOOLEAN NOT NULL DEFAULT FALSE,effective_from DATE NOT NULL,effective_to DATE,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE INDEX hr_benefit_assignments_staff_idx ON hr_benefit_assignments(tenant_id,staff_id,effective_from DESC);
CREATE TABLE hr_commission_rules(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE,name TEXT NOT NULL,basis TEXT NOT NULL CHECK(basis IN('SERVICE_REVENUE','PACKAGE_SALE','PRODUCT_SALE','COLLECTION','NEW_CUSTOMER','TARGET','TEAM_TARGET','BRANCH_TARGET')),rate DECIMAL(9,4),fixed_amount DECIMAL(14,2),currency TEXT NOT NULL DEFAULT 'TRY',staff_id TEXT REFERENCES staff(id) ON DELETE CASCADE,position_id TEXT REFERENCES hr_positions(id) ON DELETE CASCADE,scope_entity_type TEXT,scope_entity_id TEXT,effective_from DATE NOT NULL,effective_to DATE,active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL DEFAULT 1,reversal_on_refund BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(rate IS NOT NULL OR fixed_amount IS NOT NULL),CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE INDEX hr_commission_rules_scope_idx ON hr_commission_rules(tenant_id,company_id,branch_id,basis,active,effective_from);
CREATE TABLE hr_variable_earnings(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,earning_type TEXT NOT NULL CHECK(earning_type IN('COMMISSION','BONUS','REWARD')),rule_id TEXT REFERENCES hr_commission_rules(id) ON DELETE SET NULL,source_type TEXT,source_id TEXT,amount DECIMAL(14,2) NOT NULL,currency TEXT NOT NULL DEFAULT 'TRY',status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REVERSED','POSTED')),calculation_trace JSONB NOT NULL DEFAULT '{}'::jsonb,approved_by TEXT,approved_at TIMESTAMP(3),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,earning_type,source_type,source_id,staff_id));
CREATE TABLE hr_employee_advances(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,amount DECIMAL(14,2) NOT NULL CHECK(amount>0),currency TEXT NOT NULL DEFAULT 'TRY',reason TEXT,status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK(status IN('REQUESTED','APPROVED','PAID','PARTIALLY_SETTLED','SETTLED','REJECTED','CANCELLED')),repaid_amount DECIMAL(14,2) NOT NULL DEFAULT 0,payroll_deduction DECIMAL(14,2) NOT NULL DEFAULT 0,requested_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TIMESTAMP(3),closed_at TIMESTAMP(3),CHECK(repaid_amount>=0 AND repaid_amount<=amount));
CREATE INDEX hr_employee_advances_staff_idx ON hr_employee_advances(tenant_id,staff_id,status);
CREATE TABLE hr_expense_claims(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,category TEXT NOT NULL,amount DECIMAL(14,2) NOT NULL CHECK(amount>0),currency TEXT NOT NULL DEFAULT 'TRY',expense_date DATE NOT NULL,receipt_url TEXT,cost_center_id TEXT,project_id TEXT,travel_id TEXT,description TEXT,status TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN('DRAFT','SUBMITTED','APPROVED','ACCOUNTED','REIMBURSED','REJECTED','CANCELLED')),policy_result JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX hr_expense_claims_queue_idx ON hr_expense_claims(tenant_id,company_id,status,created_at);
COMMIT;
